  function applySvgProps(svg, size, color) {
    if (!svg) return "";
    const withSize = svg.replace(/<svg([^>]*)>/, (match, attrs) => {
      let next = attrs
        .replace(/\swidth="[^"]*"/, "")
        .replace(/\sheight="[^"]*"/, "")
        .replace(/\sstyle="[^"]*"/, "");
      return `<svg${next} width="${size}" height="${size}" style="color:${color}; vertical-align: middle;">`;
    });
    return withSize.replace(/(fill|stroke)="(?!none)[^"]*"/g, '$1="currentColor"');
  }

  function getIconSvg(name, type = "linear", size = "24", color = "currentColor") {
    if (!name) return "";
    const entry = iconsData[name.toLowerCase()];
    if (!entry) return "";
    const svg = entry[type] || entry["linear"] || entry["bold"] || Object.values(entry)[0] || "";
    return applySvgProps(svg, size, color);
  }

  class IconsaxIconElement extends HTMLElement {
    static get observedAttributes() {
      return ["name", "type", "size", "color"];
    }
    connectedCallback() {
      this.render();
    }
    attributeChangedCallback() {
      if (this.isConnected) this.render();
    }
    render() {
      const name = this.getAttribute("name");
      const type = this.getAttribute("type") || "linear";
      const size = this.getAttribute("size") || "24";
      const color = this.getAttribute("color") || "currentColor";
      this.innerHTML = getIconSvg(name, type, size, color);
    }
  }

  if (typeof customElements !== "undefined" && !customElements.get("iconsax-icon")) {
    customElements.define("iconsax-icon", IconsaxIconElement);
  }

  window.getIconsaxSvg = getIconSvg;
  window.IconsaxIconElement = IconsaxIconElement;
